        const random = gestures[Math.floor(Math.random() * gestures.length)];
        this.currentGesture = random;
        if (onGestureDetected) onGestureDetected(random);
      }, 4000);
    } else {
      if (this.timer) clearInterval(this.timer);
      this.currentGesture = "none";
    }
    return this.active;
  }

  stop() {
    this.active = false;
    if (this.timer) clearInterval(this.timer);
    this.currentGesture = "none";
  }
}

